using System;using System.Drawing;using System.IO;using System.Reflection;using System.Windows.Forms;
static class ThemeCheck {
 static void Assert(bool value,string message){if(!value)throw new Exception(message);}
 static double Luminance(Color c){double sum=0;double[] values={c.R/255.0,c.G/255.0,c.B/255.0},weights={.2126,.7152,.0722};for(int i=0;i<3;i++)sum+=weights[i]*(values[i]<=.04045?values[i]/12.92:Math.Pow((values[i]+.055)/1.055,2.4));return sum;}
 static double Contrast(Color a,Color b){double x=Luminance(a),y=Luminance(b);return (Math.Max(x,y)+.05)/(Math.Min(x,y)+.05);}
 static readonly BindingFlags flags=BindingFlags.NonPublic|BindingFlags.Instance;
 static void MenuGlass(){foreach(string mode in new[]{"light","dark"}){PetTheme.Set(mode);using(var background=new Form{FormBorderStyle=FormBorderStyle.None,StartPosition=FormStartPosition.Manual,Bounds=new Rectangle(100,100,640,600),BackColor=Color.RoyalBlue,TopMost=true})using(var menu=new BubbleMenu{PetAnchor=new Point(400,550)}){menu.Items.Add(new BubbleMenuItem("First"));menu.Items.Add(new BubbleMenuItem("Second"));background.Show();background.Refresh();for(int i=0;i<8;i++){Application.DoEvents();System.Threading.Thread.Sleep(10);}menu.Show(background,new Point(300,450));Application.DoEvents();var glass=(GlassBubbleForm)typeof(BubbleMenu).GetField("glass",flags).GetValue(menu);Assert(glass!=null&&!glass.Visible&&glass.Bounds==menu.Bounds,"Menu material is not aligned with the visible popup");var captured=(Bitmap)typeof(GlassBubbleForm).GetField("original",flags).GetValue(glass);Assert(captured.GetPixel(100,70).ToArgb()==Color.RoyalBlue.ToArgb(),"Menu captured itself or the wrong screen area");var mask=(Bitmap)typeof(GlassBubbleForm).GetField("shapeMask",flags).GetValue(glass);int soft=0;for(int y=0;y<30;y++)for(int x=0;x<40;x++){int alpha=mask.GetPixel(x,y).A;if(alpha>0&&alpha<255){soft++;Assert(menu.Region.IsVisible(x+.5f,y+.5f),"Menu clipped the smooth corner pixels");}}Assert(soft>10,"Menu corner lacks antialias coverage");menu.Close();Assert(glass.IsDisposed&&typeof(BubbleMenu).GetField("glass",flags).GetValue(menu)==null,"Closed menu retained its captured desktop");background.BackColor=Color.OrangeRed;background.Refresh();for(int i=0;i<8;i++){Application.DoEvents();System.Threading.Thread.Sleep(10);}menu.Show(background,new Point(300,450));Application.DoEvents();glass=(GlassBubbleForm)typeof(BubbleMenu).GetField("glass",flags).GetValue(menu);captured=(Bitmap)typeof(GlassBubbleForm).GetField("original",flags).GetValue(glass);Assert(captured.GetPixel(100,70).ToArgb()==Color.OrangeRed.ToArgb(),"Reopened menu reused an old backdrop");menu.Close();background.Close();}}}
 static void Edges(){foreach(string mode in new[]{"light","dark"}){PetTheme.Set(mode);using(var form=new GlassBubbleForm{FormBorderStyle=FormBorderStyle.None,ClientSize=new Size(400,430)}){Assert(form.Opacity==1,"Unblurred desktop leaks through the window");form.ConfigureShape(200);var original=new Bitmap(400,430);using(var g=Graphics.FromImage(original))g.Clear(Color.FromArgb(8,12,18));var blurred=new Bitmap(16,17);using(var g=Graphics.FromImage(blurred))g.Clear(Color.FromArgb(8,12,18));typeof(GlassBubbleForm).GetField("original",flags).SetValue(form,original);typeof(GlassBubbleForm).GetField("blurred",flags).SetValue(form,blurred);typeof(GlassBubbleForm).GetMethod("RebuildMaterial",flags).Invoke(form,null);var material=(Bitmap)typeof(GlassBubbleForm).GetField("material",flags).GetValue(form);Assert(Math.Abs(material.GetPixel(200,200).R-PetTheme.Surface.R)>10,"Tint hides the blurred backdrop");Assert(material.GetPixel(200,3)==material.GetPixel(200,200)&&material.GetPixel(3,200)==material.GetPixel(200,200),"Blur scaling added a bright perimeter");var mask=(Bitmap)typeof(GlassBubbleForm).GetField("shapeMask",flags).GetValue(form);int partial=0;for(int y=0;y<40;y++)for(int x=0;x<400;x++){int alpha=mask.GetPixel(x,y).A;if(alpha>0&&alpha<255)partial++;}Assert(partial>20&&mask.GetPixel(0,0).A==0&&mask.GetPixel(200,200).A==255,"Round contour lacks smooth coverage");}}}
 internal static void Run(){string original=PetTheme.Mode,path=Path.Combine(Path.GetTempPath(),"pet-theme-"+Guid.NewGuid().ToString("N")+".txt");try{Edges();MenuGlass();using(var pet=new Usagi())using(var form=(Form)typeof(Usagi).GetMethod("CreateSettingsForm",flags).Invoke(pet,null)){
  form.Show();Application.DoEvents();foreach(string mode in new[]{"light","dark","system","dark","light"}){((SettingButton)form.Controls["Theme-"+mode]).PerformClick();Assert(PetTheme.Mode==mode,"Theme selector did not apply");Assert(form.ForeColor==PetTheme.Ink,"Settings retained stale foreground");foreach(Control child in form.Controls)if(child is LinkLabel)Assert(((LinkLabel)child).LinkColor==(Equals(child.Tag,"footer")?PetTheme.FooterInk:Equals(child.Tag,"muted")?PetTheme.Muted:PetTheme.LinkInk),"Footer link invisible in theme");Assert(form.Controls["CharacterLogo"].BackColor==Color.Transparent,"Logo has an opaque square");Assert(Contrast(PetTheme.Ink,PetTheme.Surface)>=7&&Contrast(PetTheme.Muted,PetTheme.Surface)>=4.5&&Contrast(PetTheme.SelectionInk,PetTheme.Accent)>=4.5,"Theme text contrast insufficient");using(var b=new Bitmap(form.Width,form.Height))form.DrawToBitmap(b,form.ClientRectangle);PetTheme.SaveTo(path);PetTheme.Set(mode=="dark"?"light":"dark");PetTheme.LoadFrom(path);Assert(PetTheme.Mode==mode,"Theme preference not restored");}
  PetTheme.Set("dark");typeof(Usagi).GetMethod("ShowSettingsInfo",flags).Invoke(pet,new object[]{form});Assert(form.Controls["InfoPage"].ForeColor==PetTheme.Ink,"Nested info page ignored dark mode");PetTheme.Set("light");Assert(form.Controls["InfoPage"].ForeColor==PetTheme.Ink,"Open info page did not update theme");
  foreach(Control control in form.Controls)Assert(control.Bottom<=form.Height-14,"Settings control overlaps bubble tail");form.Close();}
  File.WriteAllText(path,"broken-theme");PetTheme.LoadFrom(path);Assert(PetTheme.Mode=="system","Corrupt theme did not fall back to system");
 }finally{PetTheme.Set(original);if(File.Exists(path))File.Delete(path);}Console.WriteLine("PASS: light/dark/system controls, live nested-page colors, transparent logos, preference round trip and corrupt input.");}
}
